<?php require 'config.php';$id=requireLogin();$where=['id != ?','id NOT IN (SELECT liked_id FROM likes WHERE user_id=?)'];$values=[$id,$id];if(preg_match('/^(18|26|36)-(25|35|50)$/',$_GET['age_range']??'', $m)){$where[]='age BETWEEN ? AND ?';$values[]=(int)$m[1];$values[]=(int)$m[2];}if(trim($_GET['location']??'')!==''){$where[]='location LIKE ?';$values[]='%'.trim($_GET['location']).'%';}$s=$pdo->prepare('SELECT id,name,bio,location,age,avatar FROM users WHERE '.implode(' AND ',$where).' ORDER BY id DESC LIMIT 30');$s->execute($values);respond(['success'=>true,'matches'=>$s->fetchAll(PDO::FETCH_ASSOC)]);
